function validate(input) {
  const [{ Relations = [] }] = input;
  const seen = new Set();
  for (const [user, follower] of Relations) {
    if (user === null || follower === null) return 'Every row needs a user_id and a follower_id.';
    const key = `${user}|${follower}`;
    if (seen.has(key)) return `${follower} follows ${user} twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const users = small ? 2 + Math.floor(rand() * 4) : 120;
  const followers = small ? 2 + Math.floor(rand() * 5) : 260;
  const rows = small ? Math.floor(rand() * 9) : 2000;
  // Ids come from one pool, so a user can also follow other users; nobody follows themself.
  const userIds = [], seen = new Set(), Relations = [];
  for (let i = 0; i < users; i++) userIds.push(small ? [1, 2, 3, 7, 9][i] : 1 + i * 2);
  for (let attempt = 0; Relations.length < rows && attempt < rows * 20; attempt++) {
    const user = userIds[Math.floor(rand() * userIds.length)];
    const follower = 1 + Math.floor(rand() * followers) + (small ? 0 : 1);
    if (follower === user || seen.has(`${user}|${follower}`)) continue;
    seen.add(`${user}|${follower}`);
    Relations.push([user, follower]);
  }
  return [{ Relations }];
}
